  "{0}: rosters only, no games yet": "{0}: רק סגלים, עוד אין משחקים",
  "A fan-made arcade of basketball games built on real Israeli Basketball Premier League data.": "ארקייד משחקי כדורסל שנבנה על ידי אוהדים, על בסיס נתונים אמיתיים מליגת העל בכדורסל.",
  "Account": "חשבון",
  "Clearing this site's data in your browser deletes them, or use the button below.": "ניקוי הנתונים של האתר בדפדפן מוחק אותם, או אפשר להשתמש בכפתור למטה.",
  "Current season": "העונה הנוכחית",
  "Daily reminders are off unless you switch them on. They come from your own browser, not from a server.": "תזכורות יומיות כבויות אלא אם מפעילים אותן. הן מגיעות מהדפדפן שלך, לא משרת.",
