  "Delete my data on this device": "מחיקת הנתונים שלי במכשיר הזה",
  "Deleted {0} saved item{1}. Reload to start fresh": "נמחקו {0} פריטים שמורים. טעינה מחדש תתחיל מאפס",
  "Feedback.": "משוב.",
  "Fonts load from Google Fonts, so Google's servers see a request from your browser (including your IP address). Nothing else is loaded from other sites.": "הגופנים נטענים מ־Google Fonts, כך שהשרתים של Google רואים בקשה מהדפדפן שלך (כולל כתובת ה־IP). שום דבר אחר לא נטען מאתרים אחרים.",
  "Hosting.": "אחסון.",
  "Like any website, the host (Render) keeps standard server logs, which include IP addresses.": "כמו כל אתר, ספק האחסון (Render) שומר יומני שרת רגילים, שכוללים כתובות IP.",
  "None needed": "לא צריך",
  "Not affiliated with the league or its clubs. Club names and colours are used to identify the teams; the crests are simple initials drawn by the game, not official logos.": "לא קשור לליגה או לקבוצות שלה. שמות הקבוצות והצבעים משמשים לזיהוי הקבוצות; הסמלים הם ראשי תיבות פשוטים שהמשחק מצייר, לא לוגואים רשמיים.",
  "Nothing stored on this device": "שום דבר לא שמור במכשיר הזה",
  "On your device": "במכשיר שלך",
  "Online 1v1.": "אונליין 1 על 1.",
  "Online presence.": "נוכחות אונליין.",
  "Player ratings are calculated by the game from real stats. They are not official league ratings. In My Career, seasons after {0} are simulated from the latest rosters and labelled as such.": "דירוגי השחקנים מחושבים על ידי המשחק מסטטיסטיקה אמיתית. הם לא דירוגים רשמיים של הליגה. ב\"הקריירה שלי\", עונות אחרי {0} מדומות לפי הסגלים האחרונים ומסומנות ככאלה.",
  "players · {0} clubs": "שחקנים · {0} קבוצות",
  "Players · clubs": "שחקנים · קבוצות",
  "Ratings and win/loss records are kept on the server and as a signed copy in your browser. The leaderboard shows your nickname, avatar and rating.": "הדירוגים ומאזני הניצחונות נשמרים בשרת ובעותק חתום בדפדפן שלך. טבלת המובילים מציגה את הכינוי, האווטאר והדירוג שלך.",
  "Seasons with stats": "עונות עם סטטיסטיקה",
  "Sent to this site's server": "נשלח לשרת של האתר",
  "Short version: no account, no ads, no analytics or tracking. Your progress lives in your browser.": "בקצרה: בלי חשבון, בלי פרסומות, בלי אנליטיקה או מעקב. ההתקדמות שלך נשמרת בדפדפן.",
  "Single-player games, once the site has loaded": "משחקי יחיד, אחרי שהאתר נטען",
  "Source": "מקור",
  "The arcade": "הארקייד",
  "The data": "הנתונים",
