  "Third parties": "צדדים שלישיים",
  "to {0} ({1} seasons)": "עד {0} ({1} עונות)",
  "Version": "גרסה",
  "What you write in \"Send feedback\", and the technical details if you leave that box ticked.": "מה שכותבים ב\"שליחת משוב\", והפרטים הטכניים אם התיבה הזאת נשארת מסומנת.",
  "While the arcade is open it connects to its server, so friends can see you online and invite you. It sends your nickname (\"Guest\" if you haven't set one), avatar, level and a random device ID. Your device ID is not linked to your name, email or phone.": "כשהארקייד פתוח הוא מתחבר לשרת שלו, כדי שחברים יראו שאתה אונליין ויוכלו להזמין אותך. נשלחים הכינוי (\"אורח\" אם לא הוגדר), האווטאר, הרמה ומזהה מכשיר אקראי. מזהה המכשיר לא מקושר לשם, למייל או לטלפון שלך.",
  "Works offline": "עובד בלי רשת",
  "Your settings, progress, scores, achievements, daily-challenge results, saved games and profile (nickname and avatar) are kept in your browser's local storage. They never leave the device, except for the online details below. The app sets no cookies.": "ההגדרות, ההתקדמות, הניקוד, ההישגים, תוצאות האתגרים היומיים, המשחקים השמורים והפרופיל (כינוי ואווטאר) נשמרים באחסון המקומי של הדפדפן. הם לא יוצאים מהמכשיר, חוץ מפרטי האונליין שלמטה. האפליקציה לא משתמשת בעוגיות.",
