  "An independent, non-commercial fan project. Not affiliated with the Israeli Basketball Premier League, its clubs, Winner (the Israel Sports Betting Board) or Euroleague Basketball; their names are trademarks of their owners, used only to describe the real competitions. Club colours identify the teams; the crests are simple initials drawn by the game, not official logos. No betting, money or prizes.": "פרויקט אוהדים עצמאי ולא מסחרי. לא קשור לליגת העל בכדורסל, לקבוצות שלה, לווינר (המועצה להסדר ההימורים בספורט) או ליורוליג; השמות שלהם הם סימנים מסחריים של בעליהם ומשמשים רק לתיאור המסגרות האמיתיות. צבעי הקבוצות מזהים אותן; הסמלים הם ראשי תיבות פשוטים שהמשחק מצייר, לא לוגואים רשמיים. בלי הימורים, כסף או פרסים.",
  "Data: official Israeli Basketball Premier League site (bsl.org.il), 2010-11 – 2026-27. Ratings are game-generated, not official. Not affiliated with the league, its clubs, Winner or EuroLeague. No betting. ·": "נתונים: האתר הרשמי של ליגת העל בכדורסל (bsl.org.il), 2010-11 – 2026-27. הדירוגים נוצרו במשחק ואינם רשמיים. לא קשור לליגה, לקבוצות, לווינר או ליורוליג. בלי הימורים. ·",
